"""The one-step expansion generated by the step ``s_n = n / n**n``.

Read the instruction literally: the step at index ``n`` is
``s_n = n / n**n = n**(1-n)``. Dividing the previous value by the step gives
the multiplicative expansion

    A_0 = 1,    A_n = A_{n-1} / s_n = A_{n-1} * n**(n-1),

so ``A_n = product(k**(k-1), k=1..n) = H(n) / n!``, where
``H(n) = product(k**k, k=1..n)`` is the hyperfactorial. The same step multiplies
the collapse ``B_n = B_{n-1} * s_n = 1 / A_n``, which tends to zero.

The additive expansion ``S_n = sum(s_k, k=1..n)`` converges. The module returns
an exact rational enclosure. For ``k >= n+1``,

    s_k = 1 / k**(k-1) <= (n+1)**(1-k),

so

    0 < S_inf - S_n <= 1 / (n * (n+1)**(n-1)).

The additive limit also has the exact integral representation

    S_inf = integral(0, 1, (1 - x*log(x)) * x**(-x) dx).

The first step is exactly one, ``s_1 = 1``. The zero-th step ``0 / 0**0`` is the
excluded pole, so the expansion starts at the identity rather than at zero.

This is exact bookkeeping, not a new closed form: the additive limit is
enclosed and splits into standard series, not evaluated in elementary terms.
The fuller reading is in ``STEP_EXPANSION.md``; the pole itself is in
``ZERO_AND_HOLES.md``.
"""

from __future__ import annotations

import math
from fractions import Fraction

__all__ = [
    "additive_expansion",
    "additive_interval",
    "divide_by_step",
    "expansion_term",
    "hyperfactorial",
    "log_expansion",
    "multiplicative_collapse",
    "multiplicative_expansion",
    "step",
    "tail_bound",
]


def _index(value: int, minimum: int, name: str) -> int:
    """Return ``value`` after checking that it is an integer of at least ``minimum``."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{name} must be an integer")
    if value < minimum:
        raise ValueError(f"{name} must be at least {minimum}, got {value}")
    return value


def step(n: int) -> Fraction:
    """Return the step ``n / n**n`` as an exact Fraction.

    Args:
        n: Step index, at least one.

    Returns:
        ``n**(1-n)``, reduced.

    Raises:
        ValueError: If ``n`` is not an integer or is less than one.
    """
    n = _index(n, 1, "n")
    return Fraction(n, n**n)


def divide_by_step(value: Fraction | int, n: int) -> Fraction:
    """Return ``value / step(n)`` exactly.

    This is the one-step operation named by the instruction. After ``n`` such
    divisions from one, the result is :func:`multiplicative_expansion`.

    Args:
        value: The previous value, as an integer or Fraction.
        n: Step index, at least one.

    Returns:
        ``value * n**(n-1)``, reduced.

    Raises:
        ValueError: If ``n`` is not an integer or is less than one, or if
            ``value`` is not an integer or Fraction.
    """
    n = _index(n, 1, "n")
    if isinstance(value, bool) or not isinstance(value, (int, Fraction)):
        raise ValueError("value must be an integer or Fraction")
    return Fraction(value) / step(n)


def expansion_term(n: int) -> int:
    """Return ``n**(n-1)``, the reciprocal of the step.

    Dividing by :func:`step` multiplies by this integer, so the multiplicative
    expansion stays integral.

    Args:
        n: Step index, at least one.

    Returns:
        ``n**(n-1)``.

    Raises:
        ValueError: If ``n`` is not an integer or is less than one.
    """
    n = _index(n, 1, "n")
    return int(n ** (n - 1))


def hyperfactorial(n: int) -> int:
    """Return ``H(n) = product(k**k, k=1..n)``.

    Args:
        n: Upper index, at least zero.

    Returns:
        The hyperfactorial, with ``H(0) = 1``.

    Raises:
        ValueError: If ``n`` is not an integer or is negative.
    """
    n = _index(n, 0, "n")
    result = 1
    for k in range(1, n + 1):
        result *= k**k
    return result


def multiplicative_expansion(n: int) -> int:
    """Return ``A_n = product(k**(k-1), k=1..n) = H(n) / n!``.

    This is the value after ``n`` one-step divisions by ``k / k**k``.

    Args:
        n: Number of steps, at least zero.

    Returns:
        The exact integer ``A_n``, with ``A_0 = 1``.

    Raises:
        ValueError: If ``n`` is not an integer or is negative.
    """
    n = _index(n, 0, "n")
    result = 1
    for k in range(1, n + 1):
        result *= k ** (k - 1)
    return result


def multiplicative_collapse(n: int) -> Fraction:
    """Return ``B_n = product(k / k**k, k=1..n) = 1 / A_n``.

    Args:
        n: Number of steps, at least zero.

    Returns:
        The exact reciprocal of :func:`multiplicative_expansion`.

    Raises:
        ValueError: If ``n`` is not an integer or is negative.
    """
    return Fraction(1, multiplicative_expansion(n))


def additive_expansion(n: int) -> Fraction:
    """Return ``S_n = sum(k / k**k, k=1..n)``.

    Args:
        n: Number of terms, at least zero.

    Returns:
        The exact partial sum, with ``S_0 = 0``.

    Raises:
        ValueError: If ``n`` is not an integer or is negative.
    """
    n = _index(n, 0, "n")
    total = Fraction(0)
    for k in range(1, n + 1):
        total += Fraction(k, k**k)
    return total


def tail_bound(n: int) -> Fraction:
    """Return an exact upper bound on ``S_inf - S_n``.

    For ``k >= n+1``, ``k / k**k <= (n+1)**(1-k)``, and the geometric sum gives
    ``1 / (n * (n+1)**(n-1))``.

    Args:
        n: Index after which the tail is bounded, at least one.

    Returns:
        The exact rational bound.

    Raises:
        ValueError: If ``n`` is not an integer or is less than one.
    """
    n = _index(n, 1, "n")
    return Fraction(1, n * (n + 1) ** (n - 1))


def additive_interval(n: int) -> tuple[Fraction, Fraction]:
    """Return an exact enclosure of the additive limit.

    The true limit ``S_inf`` is strictly between the two returned values:
    ``S_n < S_inf < S_n + tail_bound(n)``.

    Args:
        n: Index at which the tail is cut, at least one.

    Returns:
        ``(lower, upper)`` as exact Fractions.

    Raises:
        ValueError: If ``n`` is not an integer or is less than one.
    """
    lower = additive_expansion(n)
    return (lower, lower + tail_bound(n))


def log_expansion(n: int) -> float:
    """Return ``log(A_n) = sum((k-1) * log(k), k=1..n)``.

    This is the one-step logarithmic expansion: each step adds
    ``(n-1) * log(n) = -log(step(n))``.

    Args:
        n: Number of steps, at least zero.

    Returns:
        The logarithm of :func:`multiplicative_expansion`.

    Raises:
        ValueError: If ``n`` is not an integer or is negative.
    """
    n = _index(n, 0, "n")
    return sum((k - 1) * math.log(k) for k in range(1, n + 1))
